parts.text:
{
  "title": "قصة إنقاذ معابد أبو سمبل",
  "scenes": [
    {
      "narration": "إزاي ممكن نزيح معبد ضخم منحوت في قلب الجبل عشان ميه البحيرة مش تغرقه؟ دي حكاية أبو سمبل في جنوب مصر اللي بتورينا العزيمة.",
      "title": "موقع المعابد",
      "highlight": "جنوب مصر",
      "visual_type": "temple",
      "labels": [
        "أبو سمبل",
        "النوبة"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "narration": "سد أسوان الجديد عمل خطر كبير وميه البحيرة علت وبقت تهدد معابد رمسيس التاني الكبيرة والمعبد الصغير بتاع الملكة نفرتاري اللي كان محاط بالمخاطر.",
      "title": "خطر الغرق",
      "highlight": "ارتفاع الميه",
      "visual_type": "water",
      "labels": [
        "بحيرة ناصر",
        "خطر الغرق"
      ],
      "source_ids": [
        "mota",
        "unesco_rescue"
      ]
    },
    {
      "narration": "الموقع الأصلي بقى في خطر حقيقي، ومصر والسودان طلبوا من اليونسكو المساعدة عشان يحموا التراث ده من الضياع وسط تحديات صعبة.",
      "title": "طلب النجدة",
      "highlight": "دور اليونسكو",
      "visual_type": "map",
      "labels": [
        "مصر",
        "السودان"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "narration": "عملية إنقاذ أبو سمبل بدأت سنة {start_year}، واتجمع خبراء من كل حتة في العالم عشان يلاقوا حل عملي للمشكلة الكبيرة دي بسرعة.",
      "title": "بداية العمل",
      "highlight": "عام ١٩٦٤",
      "visual_type": "timeline",
      "labels": [
        "بدء العمل"
      ],
      "source_ids": [
        "unesco_rescue",
        "unesco_campaign"
      ]
    },
    {
      "narration": "هندسة المشروع ما كانتش سهلة أبداً، مهندسين وعلماء آثار ومعماريين اشتغلوا سوا عشان يدرسوا إزاي يفككوا الصخور من غير تأثير كبير.",
      "title": "فريق الخبراء",
      "highlight": "تعاون دولي",
      "visual_type": "network",
      "labels": [
        "مهندسين",
        "علماء آثار"
      ],
      "source_ids": [
        "unesco_rescue",
        "unesco_campaign"
      ]
    },
    {
      "narration": "الواجهة فيها تماثيل ضخمة لرمسيس التاني، وفيه تمثال اتضرر في العصور القديمة، وكل جزء هنا طلب حرص شديد ودقة عالية في كل خطوة.",
      "title": "واجهة المعبد",
      "highlight": "تماثيل ضخمة",
      "visual_type": "cutaway",
      "labels": [
        "تماثيل رمسيس"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "narration": "الناس وثقت كل قطعة وصورتها وكتبت عليها ملاحظات دقيقة عشان لما تيجي التركيبات بعدين كل حاجة ترجع مكانها المظبوط بكل حرص.",
      "title": "التوثيق الدقيق",
      "highlight": "تسجيل القطع",
      "visual_type": "grid",
      "labels": [
        "أرقام القطع",
        "التوثيق"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "narration": "المعبد المنحوت في الصخر اتقسم بعناية لشوية بلوكات عشان النقل، وكل بلوك اترقم واتعاملوا معاه كأنه قطعة تاريخية غالية على الكل.",
      "title": "تقطيع الصخور",
      "highlight": "تقسيم البلوكات",
      "visual_type": "blocks",
      "labels": [
        "تفكيك",
        "قطع صخرية"
      ],
      "source_ids": [
        "unesco_rescue",
        "unesco_campaign"
      ]
    },
    {
      "narration": "معدات الرفع نقلت البلوكات بحرص شديد، والشغل مشي خطوة بخطوة عشان الحجار التاريخية دي تفضل متحافظ عليها طول الطريق.",
      "title": "عمليات النقل",
      "highlight": "رفع الحجار",
      "visual_type": "crane",
      "labels": [
        "معدات رفع",
        "نقل آمن"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "narration": "المكان الجديد اتحدد على مسافة مرتفعة بعيد عن خطر الميه، بحوالي {height} متر فوق المستوى القديم، وحوالي {setback} متر جوه البر.",
      "title": "الموقع الجديد",
      "highlight": "ارتفاع جديد",
      "visual_type": "distance",
      "labels": [
        "٦٥ متر",
        "٢٠٠ متر"
      ],
      "source_ids": [
        "unesco_rescue"
      ]
    },
    {
      "narration": "المهندسين أعادوا تجميع البلوكات فوق بعضها بعناية فائقة، ورجعت المعالم الأساسية تبان تاني شكل ما كانت في مكانها الأصلي تقريباً.",
      "title": "إعادة التركيب",
      "highlight": "تجميع البلوكات",
      "visual_type": "assembly",
      "labels": [
        "تركيب",
        "بناء من جديد"
      ],
      "source_ids": [
        "unesco_rescue",
        "unesco_campaign"
      ]
    },
    {
      "narration": "فوق المعابد المعاد تركيبها، عملوا تل صناعي صخري عشان يدي إحساس طبيعي بأن المعابد لسه جوه جبل صخري قديم زي ما كانت.",
      "title": "التل الصناعي",
      "highlight": "صخور صناعية",
      "visual_type": "cutaway",
      "labels": [
        "تل صخري"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "narration": "المعبد لسه بيسمح بدخول الشمس جوه قدس الأقداس مرتين في السنة، ودي ظاهرة فريدة فضلت محفوظة رغم كل التغييرات الكبيرة حواليه.",
      "title": "دخول الشمس",
      "highlight": "ضوء الشمس",
      "visual_type": "sun",
      "labels": [
        "قدس الأقداس",
        "مرتين بالسنة"
      ],
      "source_ids": [
        "mota"
      ]
    },
    {
      "narration": "في سبتمبر سنة {end_year} خلصت أعمال الإنقاذ وافتتحوا الموقع الجديد، وده بين إزاي التنمية والتراث ممكن يمشوا سوا من غير تعارض.",
      "title": "الافتتاح الرسمي",
      "highlight": "سبتمبر ١٩٦٨",
      "visual_type": "legacy",
      "labels": [
        "افتتاح المعابد"
      ],
      "source_ids": [
        "unesco_campaign",
        "mota"
      ]
    },
    {
      "narration": "التجربة دي ساعدت في تطور حماية التراث الدولي وطلعت اتفاقية التراث العالمي اللي بتحمي الأماكن التاريخية المهمة في كل دول العالم.",
      "title": "حماية التراث",
      "highlight": "اتفاقية دولية",
      "visual_type": "network",
      "labels": [
        "التراث العالمي",
        "اليونسكو"
      ],
      "source_ids": [
        "unesco_campaign"
      ]
    },
    {
      "narration": "حكاية أبو سمبل بتثبت إن التعاون بين الدول بيقدر يحقق إنجازات، ومعابد النوبة فضلت واقفة تحكي تاريخ أجدادنا للأجيال الجاية كلها.",
      "title": "خلاصة الحكاية",
      "highlight": "حفظ التاريخ",
      "visual_type": "temple",
      "labels": [
        "أبو سمبل",
        "مصر"
      ],
      "source_ids": [
        "mota",
        "unesco_rescue",
        "unesco_campaign"
      ]
    }
  ]
}
